import numpy as np
import sys

# BUGFIX: Add ALL necessary storage paths before any local imports.
sys.path.append('storage/cognito')
sys.path.append('storage/verity')

try:
    from replicate_verity_sota_v1 import run_replication_attempt
except ImportError as e:
    print(f"CRITICAL ERROR: Could not import replicate_verity_sota_v1.py. Details: {e}")
    def run_replication_attempt(): return None, None

def construct_packing() -> tuple:
    centers, radii = run_replication_attempt()

    if centers is not None and radii is not None:
      # Using a conservative shrink factor from my previous experiments.
      return centers, radii * (1.0 - 1e-5)
    else:
      print("Algorithm execution failed, returning fallback packing.")
      centers = np.array([[0.1 + (i % 6) * 0.15, 0.1 + (i // 6) * 0.15] for i in range(32)])
      radii = np.full(32, 0.05)
      return centers, radii
